int main(void)
{
    /* 1. Select SYSCLK (170 MHz) as the I2C3 kernel clock source:
          CCIPR[17:16] (I2C3SEL) = 01b (SYSCLK) */
    RCC->CCIPR = (RCC->CCIPR & ~RCC_CCIPR_I2C3SEL) | RCC_CCIPR_I2C3SEL_0;

    /* 2. Enable GPIOA, GPIOC, and I2C3 peripheral clocks */
    RCC->AHB2ENR   |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1  |= RCC_APB1ENR1_I2C3EN;

    /* 3. Configure PA8 (I2C3_SCL, AF8) and PC9 (I2C3_SDA, AF8) */
    /* Alternate Function mode (10b) */
    GPIOA->MODER = (GPIOA->MODER & ~GPIO_MODER_MODE8_Msk) | (2UL << GPIO_MODER_MODE8_Pos);
    GPIOC->MODER = (GPIOC->MODER & ~GPIO_MODER_MODE9_Msk) | (2UL << GPIO_MODER_MODE9_Pos);

    /* Open-drain output type */
    GPIOA->OTYPER |= GPIO_OTYPER_OT8;
    GPIOC->OTYPER |= GPIO_OTYPER_OT9;

    /* Internal pull-up enabled (01b) */
    GPIOA->PUPDR = (GPIOA->PUPDR & ~GPIO_PUPDR_PUPD8_Msk) | (1UL << GPIO_PUPDR_PUPD8_Pos);
    GPIOC->PUPDR = (GPIOC->PUPDR & ~GPIO_PUPDR_PUPD9_Msk) | (1UL << GPIO_PUPDR_PUPD9_Pos);

    /* Very high output speed (11b) */
    GPIOA->OSPEEDR |= (3UL << GPIO_OSPEEDR_OSPEED8_Pos);
    GPIOC->OSPEEDR |= (3UL << GPIO_OSPEEDR_OSPEED9_Pos);

    /* Alternate function AF8 for PA8 and PC9 (AFRH registers) */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFUL << ((8 - 8) * 4))) | (8UL << ((8 - 8) * 4));
    GPIOC->AFR[1] = (GPIOC->AFR[1] & ~(0xFUL << ((9 - 8) * 4))) | (8UL << ((9 - 8) * 4));

    /* 4. Configure I2C3 timing while peripheral is disabled (PE = 0):
          f_I2CCLK = 170 MHz -> t_I2CCLK ~ 5.882 ns.
          PRESC = 15 -> t_PRESC = (15 + 1) * t_I2CCLK = 16 / 170 MHz ~ 94.12 ns.
          SCLL  = 56 -> t_SCLL  = (56 + 1) * t_PRESC = 57 * 94.12 ns = 5.365 us.
                        t_LOW   = t_SCLL + t_SYNC1 = 5.365 us + 11.76 ns = 5.38 us (>= 4.7 us).
          SCLH  = 47 -> t_SCLH  = (47 + 1) * t_PRESC = 48 * 94.12 ns = 4.518 us.
                        t_HIGH  = t_SCLH + t_SYNC2 = 4.518 us + 11.76 ns = 4.53 us (>= 4.0 us).
