#include "stm32g4xx.h"

void usart3_debug_init(void)
{
    /* 1. Enable GPIOB and USART3 clocks */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOBEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART3EN;

    /* 2. Configure PB10 (TX) and PB11 (RX) as Alternate Function 7 (USART3) */
    /* PB10 */
    GPIOB->MODER &= ~GPIO_MODER_MODE10_Msk;
    GPIOB->MODER |= (2U << GPIO_MODER_MODE10_Pos);  /* Alternate function mode (10b) */
    GPIOB->AFR[1] &= ~GPIO_AFRH_AFSEL10_Msk;
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL10_Pos); /* AF7 */

    /* PB11 */
    GPIOB->MODER &= ~GPIO_MODER_MODE11_Msk;
    GPIOB->MODER |= (2U << GPIO_MODER_MODE11_Pos);  /* Alternate function mode (10b) */
    GPIOB->AFR[1] &= ~GPIO_AFRH_AFSEL11_Msk;
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL11_Pos); /* AF7 */

    /* Optional: high speed for TX pin */
    GPIOB->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED10_Pos);

    /* 3. Configure baud rate:
     *    USART3 clock source at reset is PCLK1 = 170 MHz (RCC_CCIPR.USART3SEL = 00).
     *    With OVER8 = 0 (oversampling by 16):
     *    USARTDIV = fCK / Baud = 170,000,000 / 115,200 = 1475.694...
     *    BRR = round(170,000,000 / 115,200) = 1476 (0x05C4)
     */
    USART3->BRR = 1476;

    /* 4. Configure framing in CR1 and CR2:
     *    - 8 data bits: M1:M0 = 00 (in CR1, reset state)
     *    - Parity control disabled: PCE = 0 (in CR1, reset state)
     *    - Oversampling by 16: OVER8 = 0 (in CR1, reset state)
     *    - 1 stop bit: STOP[1:0] = 00 (in CR2, reset state)
     *    - Transmitter enable: TE = 1
     *    - Receiver enable: RE = 1
     */
    USART3->CR1 &= ~(USART_CR1_M1 | USART_CR1_M0 | USART_CR1_PCE | USART_CR1_OVER8);
    USART3->CR2 &= ~USART_CR2_STOP_Msk;
    USART3->CR1 |= (USART_CR1_TE | USART_CR1_RE);

    /* 5. Enable USART */
    USART3->CR1 |= USART_CR1_UE;
}

