    GPIOA->MODER |= (2U << GPIO_MODER_MODE6_Pos) | (2U << GPIO_MODER_MODE7_Pos);
    GPIOA->AFR[0] &= ~(GPIO_AFRL_AFSEL6_Msk | GPIO_AFRL_AFSEL7_Msk);
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos) | (2U << GPIO_AFRL_AFSEL7_Pos);

    /* PB10 (USART3_TX) & PB11 (USART3_RX) -> Alternate Function 7 */
    GPIOB->MODER &= ~(GPIO_MODER_MODE10_Msk | GPIO_MODER_MODE11_Msk);
    GPIOB->MODER |= (2U << GPIO_MODER_MODE10_Pos) | (2U << GPIO_MODER_MODE11_Pos);
    GPIOB->AFR[1] &= ~(GPIO_AFRH_AFSEL10_Msk | GPIO_AFRH_AFSEL11_Msk);
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos);
    GPIOB->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED10_Pos); /* High-speed TX */

    /* -------------------------------------------------------------------------
     * 3. Configure TIM3 (Shared time base for CH1 and CH2)
     * ------------------------------------------------------------------------- */
    /* 1 kHz time base: 170 MHz / (169 + 1) = 1 MHz count clock; ARR = 999 */
    TIM3->PSC = 169;
    TIM3->ARR = 999;

    /* CH1: 40% duty cycle (400 / 1000) */
    TIM3->CCR1 = 400;
    /* CH2: 50% duty cycle (500 / 1000) */
    TIM3->CCR2 = 500;

    /* Configure CH1 and CH2: PWM Mode 1 (110b), Preload enable (OCxPE = 1) */
    TIM3->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_OC2M_Msk);
    TIM3->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE
                |  (6U << TIM_CCMR1_OC2M_Pos) | TIM_CCMR1_OC2PE;

    /* Enable CH1 and CH2 outputs, active high (CC1P = 0, CC2P = 0) */
    TIM3->CCER |= TIM_CCER_CC1E | TIM_CCER_CC2E;

    /* Enable auto-reload preload and generate an update event to load shadow registers */
    TIM3->CR1 |= TIM_CR1_ARPE;
    TIM3->EGR  = TIM_EGR_UG;

    /* Start counter */
    TIM3->CR1 |= TIM_CR1_CEN;

    /* -------------------------------------------------------------------------
     * 4. Configure USART3
     * ------------------------------------------------------------------------- */
    /* Baud rate = 115200: 170,000,000 / 115,200 = 1475.694 -> BRR = 1476 */
    USART3->BRR = 1476;

    /* 8 data bits (M[1:0] = 00), No parity (PCE = 0), OVER8 = 0, 1 Stop bit */
    USART3->CR1 &= ~(USART_CR1_M1 | USART_CR1_M0 | USART_CR1_PCE | USART_CR1_OVER8);
    USART3->CR2 &= ~USART_CR2_STOP_Msk;

    /* Enable TX, RX, and USART peripheral */
    USART3->CR1 |= (USART_CR1_TE | USART_CR1_RE);
    USART3->CR1 |= USART_CR1_UE;

    /* -------------------------------------------------------------------------
     * 5. Infinite Loop
     * ------------------------------------------------------------------------- */
    while (1)
    {
    }
}
