    PWR->CR5 &= ~PWR_CR5_R1MODE;

    // 3. Configure Flash latency to 4 wait states (required for 170 MHz at Range 1 Boost)
    //    Also enable data/instruction caches and prefetch buffer
    FLASH->ACR &= ~FLASH_ACR_LATENCY;
    FLASH->ACR |= FLASH_ACR_LATENCY_4WS | FLASH_ACR_PRFTEN | FLASH_ACR_ICEN | FLASH_ACR_DCEN;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS);

