    //    PLLM = /4  -> 4 MHz (valid VCO in: 4 to 16 MHz)
    //    PLLN = *85 -> 340 MHz VCO (valid VCO out: 64 to 344 MHz)
    //    PLLR = /2  -> 170 MHz sysclk
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI |
                   (3U << RCC_PLLCFGR_PLLM_Pos) |   // PLLM = 4 (value 3)
                   (85U << RCC_PLLCFGR_PLLN_Pos) |  // PLLN = 85
                   (0U << RCC_PLLCFGR_PLLR_Pos) |   // PLLR = 2 (value 0)
                   RCC_PLLCFGR_PLLREN;              // Enable Main PLL 'R' clock output

    // 6. Enable PLL and wait for lock
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    // 7. Select PLL as system clock source (SYSCLK)
    RCC->CFGR &= ~RCC_CFGR_SW;
    RCC->CFGR |= RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

