#include "stm32g4xx.h"

int main(void)
{
    /* 1. Enable peripheral clocks for GPIOA and TIM1 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 in Alternate Function mode (AF6 = TIM1_CH1) */
    /* MODER8 = 10b (Alternate function) */
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos);

    /* High speed on PA8 */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);

    /* Output type: Push-pull (OTYPER bit 8 = 0) */
    GPIOA->OTYPER &= ~(1U << 8);

    /* No pull-up, no pull-down */
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD8_Msk;

    /* Route AF6 (TIM1_CH1) to PA8 via AFR[1] (AFRH pin 8 -> bits 3:0) */
    GPIOA->AFR[1] &= ~(0xFU << ((8 - 8) * 4));
    GPIOA->AFR[1] |= (6U << ((8 - 8) * 4));

    /* 3. Configure TIM1 time-base for 20 kHz PWM
     * Timer clock = 170 MHz (APB2 prescaler = 1 -> TIM1CLK = 170 MHz)
     * Target frequency = 20 kHz -> Period = 170,000,000 / 20,000 = 8500 counts
     * PSC = 0
     * ARR = 8500 - 1 = 8499
     * Duty cycle = 25 % -> CCR1 = 8500 * 0.25 = 2125
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;
    TIM1->CCR1 = 2125;

    /* 4. Configure Channel 1 in edge-aligned PWM Mode 1 with preload enabled */
    /* OC1M = 0110b (PWM mode 1: active while CNT < CCR1, inactive otherwise) */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (TIM_CCMR1_OC1M_1 | TIM_CCMR1_OC1M_2);
    TIM1->CCMR1 |= TIM_CCMR1_OC1PE;

    /* Enable Auto-reload preload (ARPE) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* 5. Configure channel polarity and enable output */
    /* Active high: CC1P = 0, Output enable: CC1E = 1 */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 6. Advanced timer requirement: Enable Main Output (MOE) */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 7. Generate an update event to transfer PSC, ARR, and CCR1 to active registers */
    TIM1->EGR = TIM_EGR_UG;

    /* 8. Start counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    while (1)
    {
    }
}
```

### Explanation

1. **Clock Configuration & Peripherals**:
   - `RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN` enables the clock for GPIO port A.
   - `RCC->APB2ENR |= RCC_APB2ENR_TIM1EN` enables the clock for the TIM1 advanced-control timer on APB2.

2. **Pin Multiplexing (PA8)**:
   - On the STM32G474, pin `PA8` connects to `TIM1_CH1` on Alternate Function 6 (`AF6`).
   - `GPIOA->MODER` sets mode `10b` (Alternate Function) for pin 8.
   - `GPIOA->AFR[1]` (AFRH) is configured with `0x6` at nibble 0 (corresponding to PA8).

3. **Timer Calculations**:
   - TIM1 kernel clock is $170\text{ MHz}$ ($PCLK2 = 170\text{ MHz}$, $APB2\text{ prescaler} = 1$).
   - For an up-counting edge-aligned timer, the PWM frequency is given by:
     $$f_{\text{PWM}} = \frac{f_{\text{TIM1CLK}}}{(\text{PSC} + 1) \cdot (\text{ARR} + 1)}$$
   - Setting $\text{PSC} = 0$ and $\text{ARR} = 8499$ yields:
     $$f_{\text{PWM}} = \frac{170\,000\,000}{1 \cdot 8500} = 20\,000\text{ Hz}\quad (0\%\text{ error})$$
   - For a 25% duty cycle in PWM Mode 1:
     $$\text{CCR1} = 0.25 \times (\text{ARR} + 1) = 0.25 \times 8500 = 2125\quad (0\%\text{ error})$$

4. **PWM Mode & Output Activation**:
   - `TIM1->CCMR1`: `OC1M` set to `0110b` selects PWM mode 1 (active when counter $<$ compare value). `OC1PE` enables preload.
   - `TIM1->CCER`: `CC1E = 1` enables the Channel 1 output on the pin, and `CC1P = 0` selects active-high polarity.
   - `TIM1->BDTR`: Because TIM1 is an advanced-control timer, setting the Main Output Enable (`MOE`, bit 15) bit is necessary to connect the output compare signal to the physical pad.
   - `TIM1->EGR`: Writing `UG` triggers an update event to latch the preload registers into their shadow registers immediately.
   - `TIM1->CR1`: Setting `CEN = 1` starts the counter.

