Here is the complete bare-metal C code to configure I2C3 in Standard mode (100 kHz) on the STM32G474 using CMSIS registers.

### Complete C Code

```c
#include "stm32g4xx.h"

int main(void)
{
    /* 1. Enable GPIOA and GPIOC clocks on AHB2 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN;

    /* 2. Configure PA8 (I2C3_SCL, AF2) and PC9 (I2C3_SDA, AF8) as open-drain alternate function */
    /* PA8: Alternate function mode (MODER[17:16] = 10b) */
    GPIOA->MODER = (GPIOA->MODER & ~GPIO_MODER_MODE8_Msk) | (2U << GPIO_MODER_MODE8_Pos);
    /* PA8: Open-drain output */
    GPIOA->OTYPER |= GPIO_OTYPER_OT8;
    /* PA8: Assign AF2 (I2C3_SCL) in AFR[1] (AFRH) */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFU << ((8U - 8U) * 4U))) | (2U << ((8U - 8U) * 4U));

    /* PC9: Alternate function mode (MODER[19:18] = 10b) */
    GPIOC->MODER = (GPIOC->MODER & ~GPIO_MODER_MODE9_Msk) | (2U << GPIO_MODER_MODE9_Pos);
    /* PC9: Open-drain output */
    GPIOC->OTYPER |= GPIO_OTYPER_OT9;
    /* PC9: Assign AF8 (I2C3_SDA) in AFR[1] (AFRH) */
    GPIOC->AFR[1] = (GPIOC->AFR[1] & ~(0xFU << ((9U - 8U) * 4U))) | (8U << ((9U - 8U) * 4U));

    /* 3. Select SYSCLK (170 MHz) as I2C3 kernel clock source (RCC_CCIPR.I2C3SEL = 01b) */
    RCC->CCIPR = (RCC->CCIPR & ~RCC_CCIPR_I2C3SEL_Msk) | (1U << RCC_CCIPR_I2C3SEL_Pos);

    /* 4. Enable I2C3 peripheral clock on APB1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 5. Ensure peripheral is disabled before programming TIMINGR */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /* 6. Configure I2C3_TIMINGR for Standard-mode (100 kHz)
     * Kernel clock fI2CCLK = 170 MHz (tI2CCLK = 5.882 ns)
     * PRESC = 3  -> tPRESC = (3 + 1) * tI2CCLK = 23.529 ns
     * SCLDEL = 4 -> tSCLDEL = (4 + 1) * tPRESC = 117.65 ns
     * SDADEL = 2 -> tSDADEL = 2 * tPRESC = 47.06 ns
     * SCLH = 204 -> tSCLH = (204 + 1) * tPRESC = 4823.53 ns
     * SCLL = 214 -> tSCLL = (214 + 1) * tPRESC = 5058.82 ns
