    I2C3->TIMINGR = (3U << I2C_TIMINGR_PRESC_Pos)   |
                    (4U << I2C_TIMINGR_SCLDEL_Pos)  |
                    (2U << I2C_TIMINGR_SDADEL_Pos)  |
                    (204U << I2C_TIMINGR_SCLH_Pos)  |
                    (214U << I2C_TIMINGR_SCLL_Pos);

    /* 7. Enable peripheral */
    I2C3->CR1 |= I2C_CR1_PE;

    while (1)
    {
    }
}
