    GPIOC->AFR[0] |= (6U << GPIO_AFRL_AFSEL2_Pos);

    /* 4. Configure PC2 I/O output speed to very high speed (11b) */
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED2_Pos);

    /* 5. Enable TIM20 clock on APB2 bus */
    RCC->APB2ENR |= RCC_APB2ENR_TIM20EN;

    /* 6. Configure Timer Prescaler and Auto-reload values:
     *    TIM20 input clock = 170 MHz (APB2 prescaler = 1).
     *    Target frequency = 5 kHz.
     *    PSC = 0 -> timer counter clock = 170 MHz.
     *    ARR = (170 MHz / 5000 Hz) - 1 = 33999.
     *    CCR2 = 60% of (ARR + 1) = 0.60 * 34000 = 20400.
     */
    TIM20->PSC = 0;
    TIM20->ARR = 33999;
    TIM20->CCR2 = 20400;

    /* 7. Configure TIM20 Channel 2 for PWM Mode 1 with Preload enabled:
     *    OC2M[2:0] in CCMR1 = 110b (PWM mode 1).
     *    OC2PE = 1 (Output compare 2 preload enable).
     */
    TIM20->CCMR1 &= ~TIM_CCMR1_OC2M_Msk;
    TIM20->CCMR1 |= (6U << TIM_CCMR1_OC2M_Pos) | TIM_CCMR1_OC2PE;

    /* 8. Enable Channel 2 output (CC2E = 1), default polarity active high (CC2P = 0) */
    TIM20->CCER |= TIM_CCER_CC2E;

    /* 9. Advanced timer feature: enable Main Output Enable (MOE = 1) in BDTR */
