    GPIOA->OTYPER &= ~GPIO_OTYPER_OT8;
    /* Output speed: Very High Speed (OSPEED8 = 11b) */
    GPIOA->OSPEEDR |= (GPIO_OSPEEDR_OSPEED8_0 | GPIO_OSPEEDR_OSPEED8_1);
    /* No pull-up, no pull-down (PUPD8 = 00b) */
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD8_Msk;
    /* Alternate function 6 (AF6) in AFR[1] (AFRH bits 3:0) */
    GPIOA->AFR[1] &= ~GPIO_AFRH_AFSEL8_Msk;
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos);

    /* -------------------------------------------------------------
     * 3. Configure TIM1 for 20 kHz PWM, 25% duty cycle on Channel 1
     *    Timer clock = 170 MHz.
     *    ARR = 8499 (period = 8500 counts -> 20 kHz).
     *    CCR1 = 2125 (25% of 8500 counts).
     * ------------------------------------------------------------- */
    TIM1->PSC = 0U;
    TIM1->ARR = 8499U;
    TIM1->CCR1 = 2125U;

    /* Channel 1: PWM Mode 1 (OC1M = 0110b) with preload enabled (OC1PE = 1) */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (TIM_CCMR1_OC1M_1 | TIM_CCMR1_OC1M_2 | TIM_CCMR1_OC1PE);

    /* Enable output on Channel 1, active-high polarity (CC1P = 0) */
    TIM1->CCER &= ~(TIM_CCER_CC1P | TIM_CCER_CC1NP);
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Enable Auto-reload preload (ARPE) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Main Output Enable (MOE) for advanced timer TIM1 */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Generate update event (UG) to load prescaler and reload values into shadow registers */
    TIM1->EGR = TIM_EGR_UG;

    /* Enable TIM1 counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    /* -------------------------------------------------------------
     * 4. Configure PC8 (I2C3_SCL) and PC9 (I2C3_SDA) as AF8 Open-Drain
     * ------------------------------------------------------------- */
    /* Alternate function mode (MODER8 = 10b, MODER9 = 10b) */
    GPIOC->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOC->MODER |= (GPIO_MODER_MODE8_1 | GPIO_MODER_MODE9_1);
    /* Output type: Open-Drain (OT8 = 1, OT9 = 1) */
    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);
    /* Output speed: Very High Speed (OSPEED8 = 11b, OSPEED9 = 11b) */
    GPIOC->OSPEEDR |= (GPIO_OSPEEDR_OSPEED8_Msk | GPIO_OSPEEDR_OSPEED9_Msk);
    /* Enable internal pull-ups (PUPD8 = 01b, PUPD9 = 01b) */
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);
    GPIOC->PUPDR |= (GPIO_PUPDR_PUPD8_0 | GPIO_PUPDR_PUPD9_0);
    /* Select AF8 (I2C3) on PC8 and PC9 in AFR[1] (AFRH) */
    GPIOC->AFR[1] &= ~(GPIO_AFRH_AFSEL8_Msk | GPIO_AFRH_AFSEL9_Msk);
    GPIOC->AFR[1] |= ((8U << GPIO_AFRH_AFSEL8_Pos) | (8U << GPIO_AFRH_AFSEL9_Pos));

    /* -------------------------------------------------------------
     * 5. Configure I2C3 controller in Standard Mode (100 kHz)
     *    Kernel clock = 16 MHz (HSI16).
     *    TIMINGR = PRESC:3, SCLDEL:4, SDADEL:2, SCLH:0x0F, SCLL:0x13
     * ------------------------------------------------------------- */
    /* Ensure peripheral is disabled (PE = 0) before writing TIMINGR */
    I2C3->CR1 &= ~I2C_CR1_PE;

    I2C3->TIMINGR = (3U << 28) | (4U << 20) | (2U << 16) | (0x0FU << 8) | (0x13U << 0);

    /* Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;

    /* Loop forever */
    while (1) {
    }
}
