    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS) {
        /* Wait for Flash latency to take effect */
    }

    /* Switch to Range 1 Boost mode: clear R1MODE bit (bit 8) in PWR_CR5 */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* -------------------------------------------------------------------------
     * 2. CLOCK INITIALIZATION (HSE 12 MHz -> PLL -> 170 MHz SYSCLK)
     * ------------------------------------------------------------------------- */
    /* Enable HSE oscillator */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY)) {
        /* Wait until HSE is ready */
    }

    /* Configure PLL:
     * Source = HSE (12 MHz)
     * PLLM   = 3  -> VCO in = 12 / 3 = 4 MHz (PLLM bits: value - 1 = 2)
     * PLLN   = 85 -> VCO out = 4 * 85 = 340 MHz
     * PLLR   = 2  -> SYSCLK = 340 / 2 = 170 MHz (PLLR bits: 00 = div 2)
     */
    RCC->PLLCFGR = (3U << RCC_PLLCFGR_PLLSRC_Pos)       /* HSE source */
                 | ((3U - 1U) << RCC_PLLCFGR_PLLM_Pos)  /* PLLM = 3 */
                 | (85U << RCC_PLLCFGR_PLLN_Pos)        /* PLLN = 85 */
                 | (0U << RCC_PLLCFGR_PLLR_Pos)         /* PLLR = 2 */
                 | RCC_PLLCFGR_PLLREN;                  /* Enable PLLR output */

    /* Enable PLL */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Wait until PLL is locked */
    }

    /* Select PLL as system clock source */
    RCC->CFGR &= ~RCC_CFGR_SW;
    RCC->CFGR |= RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
        /* Wait until system clock switch is complete */
    }

    /* -------------------------------------------------------------------------
     * 3. GPIO PIN CONFIGURATION
     * ------------------------------------------------------------------------- */
    /* Enable GPIOA and GPIOB clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOBEN;

    /* --- USART2 Pins (PA2: TX, PA3: RX) --- */
    /* PA2: Alternate Function AF7 (USART2_TX), High speed, Push-pull */
    GPIOA->MODER &= ~(GPIO_MODER_MODE2_Msk | GPIO_MODER_MODE3_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE2_Pos) | (2U << GPIO_MODER_MODE3_Pos); /* AF mode */

    GPIOA->AFR[0] &= ~((0xFU << GPIO_AFRL_AFSEL2_Pos) | (0xFU << GPIO_AFRL_AFSEL3_Pos));
    GPIOA->AFR[0] |= (7U << GPIO_AFRL_AFSEL2_Pos) | (7U << GPIO_AFRL_AFSEL3_Pos); /* AF7 */

    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED2_Pos) | (3U << GPIO_OSPEEDR_OSPEED3_Pos);
    GPIOA->OTYPER  &= ~(GPIO_OTYPER_OT2 | GPIO_OTYPER_OT3);  /* Push-pull */
    GPIOA->PUPDR   &= ~(GPIO_PUPDR_PUPD2_Msk | GPIO_PUPDR_PUPD3_Msk);
    GPIOA->PUPDR   |= (1U << GPIO_PUPDR_PUPD3_Pos);          /* Pull-up on RX idle */

    /* --- I2C1 Pins (PB8: SCL, PB9: SDA) --- */
    /* PB8, PB9: Alternate Function AF4 (I2C1), Open-drain */
    GPIOB->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOB->MODER |= (2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos); /* AF mode */

    GPIOB->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL8_Pos) | (0xFU << GPIO_AFRH_AFSEL9_Pos));
    GPIOB->AFR[1] |= (4U << GPIO_AFRH_AFSEL8_Pos) | (4U << GPIO_AFRH_AFSEL9_Pos); /* AF4 */

    GPIOB->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);    /* Open-Drain */
    GPIOB->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos) | (3U << GPIO_OSPEEDR_OSPEED9_Pos);
    GPIOB->PUPDR   &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk); /* External pull-ups exist */

    /* -------------------------------------------------------------------------
     * 4. USART2 PERIPHERAL CONFIGURATION (921600 Baud, 8N1)
     * ------------------------------------------------------------------------- */
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN;

    /* Disable USART2 before configuration */
    USART2->CR1 = 0U;

    /* Set baud rate: 170 MHz / 921600 = 184 (0xB8), error +0.25% */
    USART2->BRR = 184U;

    /* Enable Transmitter and Receiver, and enable USART2 */
    USART2->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* -------------------------------------------------------------------------
     * 5. I2C1 PERIPHERAL CONFIGURATION (100 kHz Standard Mode)
     * ------------------------------------------------------------------------- */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C1EN;

    /* Disable I2C1 before setting timing */
    I2C1->CR1 &= ~I2C_CR1_PE;

    /* Configure 100 kHz standard mode timing for 170 MHz I2C clock */
    /* PRESC = 0x3, SCLDEL = 0x4, SDADEL = 0x2, SCLH = 0xC3, SCLL = 0xC7 */
    I2C1->TIMINGR = (0x3U << I2C_TIMINGR_PRESC_Pos)
                  | (0x4U << I2C_TIMINGR_SCLDEL_Pos)
                  | (0x2U << I2C_TIMINGR_SDADEL_Pos)
                  | (0xC3U << I2C_TIMINGR_SCLH_Pos)
                  | (0xC7U << I2C_TIMINGR_SCLL_Pos);

    /* Enable I2C1 peripheral */
    I2C1->CR1 |= I2C_CR1_PE;

    /* -------------------------------------------------------------------------
     * Main loop
     * ------------------------------------------------------------------------- */
    while (1) {
        /* Background processing */
    }
}
