    /* Enable HSE oscillator */
    RCC->CR |= RCC_CR_HSEON;

    /* Wait until HSE is stable and ready to use */
    while ((RCC->CR & RCC_CR_HSERDY) == 0) {
        /* Wait loop (a timeout counter can be added in production code) */
    }
}
```

